nextflow_process {

    name "Test Process BCFTOOLS_ROHVIZ"
    script "../main.nf"
    process "BCFTOOLS_ROHVIZ"

    tag "modules"
    tag "modules_nfcore"
    tag "bcftools"
    tag "bcftools/roh"
    tag "bcftools/rohviz"


    setup {

        run("BCFTOOLS_ROH") {
            script "../../roh/main.nf"
            process {
                """
                input[0] = [ [ id:'test' ], // meta map
				    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/vcf/test.vcf.gz', checkIfExists: true),
				    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/vcf/test.vcf.gz.tbi', checkIfExists: true)
                ]
                input[1] = [[],[]]
                input[2] = []
                input[3] = []
                input[4] = []
                input[5] = []
                """
            }
        }
    }

    test("sarscov2 - bcftools-rohviz") {

        when {
            process {
                """
                input[0] = BCFTOOLS_ROH.out.roh
                input[1] = [ [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/vcf/test.vcf.gz', checkIfExists: true)
                ]
                input[2] = []
                input[3] = []
                """
            }
        }


        then {
            assertAll(
                { assert snapshot(
                    file(process.out.html[0][1]).name,
                    path(process.out.html[0][1]).readLines().size(),
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }

    }

    test("test-bcftools-rohviz-stub") {
        options '-stub'
        when {
            process {
                """
                input[0] = BCFTOOLS_ROH.out.roh
                input[1] = [ [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/vcf/test.vcf.gz', checkIfExists: true)
                ]
                input[2] = []
                input[3] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}
